public class OrderService {
    public Order getOrder(String id) {
        try {
            return repository.findById(id);
        } catch (DataAccessException e) {
            // Wrapping: Preserve root cause for logs
            throw new OrderNotFoundException("Order lookup failed", e);
        }
    }
}

@ControllerAdvice
public class GlobalExceptionHandler {
    @ExceptionHandler(OrderNotFoundException.class)
    public ResponseEntity<ErrorResponse> handle(OrderNotFoundException ex) {
        // Translation: Map to public API contract
        return ResponseEntity.status(HttpStatus.NOT_FOUND)
            .body(new ErrorResponse("ERR_001", "Order not found"));
    }
}
